 {id:"zincair",name:"아연공기 · Zn-air",group:"1차전지",stage:"상용",left:"Zn",right:"공기 O₂",carrier:"OH⁻",direction:"left",electrolyte:"알칼리 전해질을 통해 OH⁻가 공기극에서 아연극으로 이동한다.",reaction:"방전 전체: 2Zn + O₂ → 2ZnO",principle:"외부 공기에서 들어온 산소가 양극 반응물이고 아연이 산화된다.",pros:"셀 내부에 산소를 저장하지 않아 소형에서 에너지 밀도가 높다.",cons:"공기 유입·습도 관리가 필요하고 대다수 소비자 제품은 일회용이다.",materials:"아연·공기극 촉매",uses:"보청기, 소형 의료기기",sales:"2025년 글로벌 화학별 판매량 미확인",price:"kWh당 팩 가격 비교 부적절",sources:["doe"]},
 {id:"vrfb",name:"바나듐 흐름전지 · 탱크 순환형",group:"2차전지",subtype:"흐름전지",stage:"상용",left:"V²⁺/V³⁺ 탱크",right:"VO²⁺/VO₂⁺ 탱크",carrier:"H⁺",direction:"right",electrolyte:"바나듐 이온이 녹은 두 전해액을 펌프로 순환시킨다. 막을 지나는 H⁺ 방향은 운전 조건과 표시한 반응 기준에 따른 개념도다.",reaction:"방전: V²⁺ → V³⁺ + e⁻ / VO₂⁺ + 2H⁺ + e⁻ → VO²⁺ + H₂O",principle:"흐름전지는 에너지를 담은 전해액을 외부 탱크에 저장하고 펌프로 순환시키는 2차전지다. 서로 다른 산화 상태의 바나듐 전해액을 사용한다. 출력은 스택, 저장량은 탱크 크기와 농도가 좌우한다.",pros:"긴 운전 시간과 반복 사이클, 탱크 확장에 유리하다.",cons:"바나듐 전해액·탱크·펌프 비용, 낮은 에너지 밀도",materials:"바나듐 공급·가격 및 전해액 금융비용이 중요하다.",uses:"태양광·풍력 연계, 장시간 전력망 저장",sales:"2025년 글로벌 기술별 GWh 판매 비교값 미확인",price:"2025년 공통 기준 시스템 $/kWh 미확인",sources:["flow","minerals"]},
 {id:"znbr",name:"아연브롬 흐름전지 · 탱크 순환형",group:"2차전지",subtype:"흐름전지",stage:"상용·실증",left:"Zn",right:"Br₂/Br⁻",carrier:"Zn²⁺",direction:"right",electrolyte:"아연·브롬 성분의 전해액이 순환한다.",reaction:"방전 전체: Zn + Br₂ → ZnBr₂",principle:"전해액을 탱크에서 반응부로 순환시키는 2차전지다. 충전 때 아연을 석출하고 브롬을 생성하며 방전 때 역반응이 일어난다.",pros:"장시간 저장과 원료 다양화 가능성",cons:"브롬 취급·부식, 보조기기와 수율 관리가 필요하다.",materials:"아연·브롬",uses:"전력망 장시간 저장, 마이크로그리드",sales:"2025년 통일된 글로벌 GWh 판매량 미확인",price:"2025년 공통 기준 시스템 $/kWh 미확인",sources:["flow"]},
 {id:"pemfc",name:"고분자전해질 연료전지 · PEMFC",group:"연료전지",stage:"상용",left:"수소 H₂",right:"산소 O₂",carrier:"H⁺",direction:"right",electrolyte:"고분자막이 H⁺를 통과시키고 전자는 차단한다.",reaction:"수소극: H₂ → 2H⁺ + 2e⁻ / 공기극: ½O₂ + 2H⁺ + 2e⁻ → H₂O",principle:"수소와 공기가 계속 공급될 때 전기를 만든다. 연료 공급이 멈추면 발전도 멈춘다.",pros:"낮은 작동 온도, 빠른 시동, 운전 중 물 배출",cons:"수소 생산·저장·충전 인프라와 백금 촉매 비용",materials:"백금은 희토류가 아닌 백금족 금속이다. 촉매 사용량은 설계에 따라 다르다.",uses:"수소차, 지게차, 이동·비상전원",sales:"2025년 배터리 GWh와 직접 비교 가능한 판매량 없음",price:"$/kW와 수소 $/kg로 평가",sources:["fuel","fuelBasics","minerals"]},
 {id:"sofc",name:"고체산화물 연료전지 · SOFC",group:"연료전지",stage:"상용·확대",left:"연료 H₂/개질가스",right:"공기 O₂",carrier:"O²⁻",direction:"left",electrolyte:"고온 세라믹 전해질을 산화물 이온 O²⁻가 통과한다.",reaction:"공기극: ½O₂ + 2e⁻ → O²⁻ / 연료극: H₂ + O²⁻ → H₂O + 2e⁻",principle:"공기극에서 생긴 산화물 이온이 연료극으로 이동해 연료와 반응한다. 전자는 외부 회로로 돌아간다.",pros:"높은 전기 효율, 열병합과 연료 선택 폭",cons:"고온 유지·느린 시동·열순환 내구성 관리",materials:"세라믹·니켈 등 설계별 상이; 백금이 반드시 필요한 것은 아니다.",uses:"건물·데이터센터·분산전원",sales:"2025년 배터리 GWh와 직접 비교 불가",price:"$/kW·발전원가로 평가",sources:["fuel"]},
 {id:"pafc",name:"인산형 연료전지 · PAFC",group:"연료전지",stage:"상용",left:"수소 H₂",right:"산소 O₂",carrier:"H⁺",direction:"right",electrolyte:"인산 전해질을 H⁺가 통과한다.",reaction:"H₂ → 2H⁺ + 2e⁻ / ½O₂ + 2H⁺ + 2e⁻ → H₂O",principle:"인산을 이온 통로로 쓰고 연료와 공기를 공급해 전기를 얻는다.",pros:"분산전원·열병합 운전 경험",cons:"촉매 비용과 시동 시간, 열 관리",materials:"백금족 촉매가 비용 요소",uses:"건물·산업체 분산형 열병합",sales:"2025년 동일 기준 글로벌 판매량 미확인",price:"$/kW·발전원가로 평가",sources:["fuel"]},
 {id:"mcfc",name:"용융탄산염 연료전지 · MCFC",group:"연료전지",stage:"상용",left:"연료 H₂/가스",right:"O₂ + CO₂",carrier:"CO₃²⁻",direction:"left",electrolyte:"고온의 용융 탄산염에서 CO₃²⁻가 공기극에서 연료극으로 이동한다.",reaction:"공기극: ½O₂ + CO₂ + 2e⁻ → CO₃²⁻ / 연료극: H₂ + CO₃²⁻ → H₂O + CO₂ + 2e⁻",principle:"탄산 이온이 연료극으로 이동하며 연료의 화학 에너지를 전기로 바꾼다.",pros:"대형 분산전원, 고온 폐열 활용 가능",cons:"부식성 전해질·고온에 따른 수명과 유지보수",materials:"니켈 등 사용; 귀금속 촉매를 필수로 하지 않는 설계",uses:"산업·건물 분산전원",sales:"2025년 동일 기준 글로벌 판매량 미확인",price:"$/kW·발전원가로 평가",sources:["fuel"]},
 {id:"afc",name:"알칼리형 연료전지 · AFC",group:"연료전지",stage:"특수·실증",left:"수소 H₂",right:"산소 O₂",carrier:"OH⁻",direction:"left",electrolyte:"알칼리 전해질에서 OH⁻가 공기극에서 연료극으로 이동한다.",reaction:"공기극: ½O₂ + H₂O + 2e⁻ → 2OH⁻ / 연료극: H₂ + 2OH⁻ → 2H₂O + 2e⁻",principle:"수산화 이온이 산소극에서 수소극으로 이동한다.",pros:"반응 속도가 빠르고 비귀금속 촉매 선택지가 있다.",cons:"CO₂에 민감해 공기·전해질 관리가 필요하다.",materials:"촉매 조성별 상이; 반드시 백금이 필요한 것은 아니다.",uses:"우주·특수전원, 일부 이동형",sales:"2025년 동일 기준 글로벌 판매량 미확인",price:"$/kW·발전원가로 평가",sources:["fuel"]},
 {id:"dmfc",name:"직접메탄올 연료전지 · DMFC",group:"연료전지",stage:"제한적 상용",left:"메탄올 CH₃OH",right:"산소 O₂",carrier:"H⁺",direction:"right",electrolyte:"고분자막을 H⁺가 통과한다.",reaction:"연료극: CH₃OH + H₂O → CO₂ + 6H⁺ + 6e⁻ / 공기극: 1½O₂ + 6H⁺ + 6e⁻ → 3H₂O",principle:"액체 메탄올을 별도 개질 없이 전극에서 직접 산화한다.",pros:"액체 연료 보급·보관이 수소보다 간단할 수 있다.",cons:"연료 투과와 촉매 비용, 낮은 출력 밀도, CO₂ 배출",materials:"백금·루테늄 등 촉매가 비용 요인",uses:"원격 센서, 휴대·장시간 보조전원",sales:"2025년 동일 기준 글로벌 판매량 미확인",price:"$/kW·연료비로 평가",sources:["fuelBasics","fuel"]}
